/// A report generated by an [AlgorithmStep] after its execution.
///
/// Contains a summary of the work done, the duration, and any
/// relevant metadata for logging or debugging purposes.
class StepReport {
  final String stepName;
  final String summary;
  final Duration duration;
  final Map<String, dynamic> details;

  StepReport({
    required this.stepName,
    required this.summary,
    required this.duration,
    this.details = const {},
  });

  @override
  String toString() {
    return '[$stepName] - ${duration.inMilliseconds}ms: $summary';
  }
}